// Typed model-output presentation; these tags are generated by the local model.
export function splitModelOutput(text) {
  const sections = [];
  let at = 0;
  while (at < text.length) {
    const start = text.indexOf('<think>', at);
    if (start < 0) { sections.push({kind:'answer',text:text.slice(at)}); break; }
    if (start > at) sections.push({kind:'answer',text:text.slice(at,start)});
    const contentStart = start + 7;
    const close = text.indexOf('</think>',contentStart);
    if (close < 0) {
      sections.push({kind:'think',text:text.slice(contentStart)});
      break;
    }
    sections.push({kind:'think',text:text.slice(contentStart,close)});
    at = close + 8;
  }
  return sections;
}

export function streamForChat(stream, chatId) {
  return stream?.chatId === chatId ? (stream.text ?? '') : '';
}
